# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! The human-edit diff: churn, leftover lines, and the fallback for huge bodies.

// Unwrapping is fine in tests (AGENTS.md); the workspace lints keep it out of
// library code.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use tiny_artifacts::{ArtifactAuthor, ArtifactDiff, ArtifactVersion, DiffOp, MAX_DIFF_LINES};

fn version(n: u32, body: &str) -> ArtifactVersion {
    ArtifactVersion::new(n, body, ArtifactAuthor::Agent, "agent", 0)
}

fn ops(diff: &ArtifactDiff) -> Vec<(DiffOp, String)> {
    diff.lines.iter().map(|l| (l.op, l.text.clone())).collect()
}

#[test]
fn writing_into_an_empty_version_is_total_churn_and_no_change_is_none() {
    let added = ArtifactDiff::between(&version(1, ""), &version(2, "a\nb"));
    assert_eq!(added.added, 2);
    assert!((added.churn - 1.0).abs() < f64::EPSILON);

    let same = ArtifactDiff::between(&version(1, ""), &version(2, ""));
    assert!(same.churn.abs() < f64::EPSILON);
    assert!(same.lines.is_empty());
}

#[test]
fn trailing_removals_and_additions_are_kept_in_order() {
    let cut = ArtifactDiff::between(&version(1, "a\nb\nc"), &version(2, "a"));
    assert_eq!(
        ops(&cut),
        [
            (DiffOp::Equal, "a".into()),
            (DiffOp::Delete, "b".into()),
            (DiffOp::Delete, "c".into()),
        ]
    );
    assert_eq!(cut.removed, 2);

    let grown = ArtifactDiff::between(&version(1, "a"), &version(2, "a\nb\nc"));
    assert_eq!(
        ops(&grown),
        [
            (DiffOp::Equal, "a".into()),
            (DiffOp::Insert, "b".into()),
            (DiffOp::Insert, "c".into()),
        ]
    );
}

#[test]
fn a_huge_body_degrades_to_a_whole_replace() {
    let big = (0..=MAX_DIFF_LINES)
        .map(|i| format!("line {i}"))
        .collect::<Vec<_>>()
        .join("\n");
    let diff = ArtifactDiff::between(&version(1, "old"), &version(2, &big));
    assert_eq!(diff.removed, 1);
    assert_eq!(diff.added, MAX_DIFF_LINES + 1);
    assert_eq!(diff.lines[0].op, DiffOp::Delete);
    assert!(diff.lines[1..].iter().all(|l| l.op == DiffOp::Insert));
}

//! File references: helpers, media types, and paths that cannot be read.

// Unwrapping is fine in tests (AGENTS.md); the workspace lints keep it out of
// library code.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::path::{Path, PathBuf};

use tiny_artifacts::{media_type_for, FileRef, FileRefError, FileRoots};

fn dir() -> PathBuf {
    let dir = std::env::temp_dir().join(format!("tiny-artifacts-ref-{}", uuid::Uuid::new_v4()));
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

#[tokio::test]
async fn a_resolved_reference_knows_its_name_extension_and_type() {
    let root = dir();
    std::fs::write(root.join("Report.PDF"), b"%PDF").unwrap();
    let roots = FileRoots::new([root.clone()]);
    assert_eq!(roots.roots(), [root]);

    let file = roots.resolve("Report.PDF").await.unwrap();
    assert_eq!(file.file_name(), Some("Report.PDF"));
    assert_eq!(file.extension().as_deref(), Some("pdf"));
    assert_eq!(file.media_type.as_deref(), Some("application/pdf"));
    assert_eq!(file.size_bytes, 4);

    let bare = FileRef {
        path: "/tmp/README".into(),
        size_bytes: 0,
        media_type: None,
    };
    assert_eq!(bare.extension(), None);
}

#[test]
fn media_types_cover_the_common_artifact_formats() {
    let cases = [
        ("a.png", Some("image/png")),
        ("a.jpeg", Some("image/jpeg")),
        ("a.gif", Some("image/gif")),
        ("a.webp", Some("image/webp")),
        ("a.svg", Some("image/svg+xml")),
        ("a.mp4", Some("video/mp4")),
        ("a.webm", Some("video/webm")),
        ("a.mov", Some("video/quicktime")),
        (
            "a.docx",
            Some("application/vnd.openxmlformats-officedocument.wordprocessingml.document"),
        ),
        (
            "a.pptx",
            Some("application/vnd.openxmlformats-officedocument.presentationml.presentation"),
        ),
        (
            "a.xlsx",
            Some("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"),
        ),
        ("a.csv", Some("text/csv")),
        ("a.json", Some("application/json")),
        ("a.zip", Some("application/zip")),
        ("a.md", Some("text/markdown")),
        ("a.htm", Some("text/html")),
        ("a.txt", Some("text/plain")),
        ("a.unknown", None),
        ("no-extension", None),
    ];
    for (name, expected) in cases {
        assert_eq!(media_type_for(Path::new(name)), expected, "{name}");
    }
}

#[tokio::test]
async fn an_empty_path_is_refused() {
    let roots = FileRoots::new([dir()]);
    assert!(matches!(
        roots.resolve("   ").await,
        Err(FileRefError::Empty)
    ));
}

#[cfg(unix)]
#[tokio::test]
async fn a_path_that_cannot_be_read_is_an_io_error() {
    use std::os::unix::fs::PermissionsExt;
    let root = dir();
    let locked = root.join("locked");
    std::fs::create_dir_all(&locked).unwrap();
    std::fs::write(locked.join("f.txt"), b"x").unwrap();
    std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o000)).unwrap();

    let result = FileRoots::new([root]).resolve("locked/f.txt").await;
    std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o755)).unwrap();
    // Root can read anything; the refusal only shows for an ordinary user.
    if let Err(err) = result {
        assert!(matches!(err, FileRefError::Io { .. }), "{err}");
        assert!(err.to_string().contains("locked/f.txt"));
    }
}

#[tokio::test]
async fn the_host_guard_refuses_a_path_inside_the_roots() {
    let root = dir();
    std::fs::create_dir_all(root.join(".ssh")).unwrap();
    std::fs::write(root.join(".ssh").join("id_ed25519"), b"key").unwrap();
    std::fs::write(root.join("notes.txt"), b"fine").unwrap();
    let roots = FileRoots::new([root.clone()]).with_guard(|path| {
        path.components()
            .any(|c| c.as_os_str() == ".ssh")
            .then(|| "a credential store".to_string())
    });

    // Checked on the canonical path, whatever the spelling.
    for raw in [".ssh/id_ed25519", "./.ssh/id_ed25519"] {
        let result = roots.resolve(raw).await;
        assert!(
            matches!(
                &result,
                Err(FileRefError::Refused { path, reason })
                    if path == raw && reason == "a credential store"
            ),
            "{raw}: {result:?}"
        );
    }
    let err = roots.resolve(".ssh/id_ed25519").await.unwrap_err();
    assert!(err
        .to_string()
        .contains("cannot be referenced: a credential store"));
    assert!(roots.resolve("notes.txt").await.is_ok());
}

#[test]
fn a_guard_shows_in_debug_and_equality() {
    let plain = FileRoots::new([PathBuf::from("/a")]);
    let guarded = plain.clone().with_guard(|_| None);
    assert!(format!("{guarded:?}").contains("guard: true"));
    assert!(format!("{plain:?}").contains("guard: false"));
    assert_ne!(plain, guarded);
    assert_eq!(guarded, guarded.clone());
    assert_eq!(plain, FileRoots::new([PathBuf::from("/a")]));
    assert_ne!(guarded, plain.clone().with_guard(|_| None));
}

//! Integration test for the artifact tools: create → read → update → list,
//! verifying the versioned record model and tool responses.

// Unwrapping is fine in tests (AGENTS.md); the workspace lints keep it out of
// library code.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::sync::Arc;

use tiny_artifacts::{
    ArtifactAuthor, ArtifactRecord, ArtifactStore, ArtifactVersion, Artifacts, Author,
    CreateArtifactTool, ListArtifactsTool, ReadArtifactTool, UpdateArtifactTool,
};
use tinytools::Tool;

/// A trivial in-memory store for testing tools without filesystem I/O.
struct MemStore(std::sync::Mutex<Vec<ArtifactRecord>>);

#[async_trait::async_trait]
impl ArtifactStore for MemStore {
    async fn list(&self) -> anyhow::Result<Vec<ArtifactRecord>> {
        let mut records = self.0.lock().unwrap().clone();
        records.sort_by_key(|r| std::cmp::Reverse(r.updated_at_millis));
        Ok(records)
    }
    async fn get(&self, id: &str) -> anyhow::Result<Option<ArtifactRecord>> {
        Ok(self.0.lock().unwrap().iter().find(|r| r.id == id).cloned())
    }
    async fn upsert(&self, artifact: &ArtifactRecord) -> anyhow::Result<()> {
        let mut store = self.0.lock().unwrap();
        if let Some(existing) = store.iter_mut().find(|r| r.id == artifact.id) {
            *existing = artifact.clone();
        } else {
            store.push(artifact.clone());
        }
        Ok(())
    }
    async fn delete(&self, id: &str) -> anyhow::Result<bool> {
        let mut store = self.0.lock().unwrap();
        let len = store.len();
        store.retain(|r| r.id != id);
        Ok(store.len() < len)
    }
}

#[tokio::test]
async fn create_read_update_list() {
    let store: Arc<dyn ArtifactStore> = Arc::new(MemStore(std::sync::Mutex::new(Vec::new())));
    let artifacts = Arc::new(Artifacts::new(store));
    let create = CreateArtifactTool::new(artifacts.clone(), Author::agent("agent"));
    let read = ReadArtifactTool::new(artifacts.clone());
    let update = UpdateArtifactTool::new(artifacts.clone(), Author::agent("agent"));
    let list = ListArtifactsTool::new(artifacts.clone());

    // Step 1: create
    let args = serde_json::json!({
        "kind": "markdown",
        "title": "Release Notes",
        "body": "## v1.0\nReleased on time."
    });
    let result = create.execute(args).await.unwrap();
    assert!(!result.is_error, "create should succeed: {}", result.text());
    let data: serde_json::Value = serde_json::from_str(&result.text()).unwrap();
    let id = data["artifact_id"].as_str().unwrap().to_string();
    assert_eq!(data["title"], "Release Notes");
    assert_eq!(data["version"], 1);

    // Step 2: read — verify version 1
    let result = read
        .execute(serde_json::json!({ "artifact_id": &id }))
        .await
        .unwrap();
    assert!(!result.is_error);
    let record: ArtifactRecord = serde_json::from_str(&result.text()).unwrap();
    assert_eq!(record.title, "Release Notes");
    assert_eq!(record.versions.len(), 1);
    assert_eq!(record.versions[0].body, "## v1.0\nReleased on time.");
    assert_eq!(record.versions[0].author, ArtifactAuthor::Agent);

    // Step 3: update — push version 2
    let result = update
        .execute(serde_json::json!({
            "artifact_id": &id,
            "body": "## v1.1\nFixed the critical bug."
        }))
        .await
        .unwrap();
    assert!(!result.is_error, "update should succeed: {}", result.text());
    let data: serde_json::Value = serde_json::from_str(&result.text()).unwrap();
    assert_eq!(data["version"], 2);

    // Step 4: read again — verify v2
    let result = read
        .execute(serde_json::json!({ "artifact_id": &id }))
        .await
        .unwrap();
    assert!(!result.is_error);
    let record: ArtifactRecord = serde_json::from_str(&result.text()).unwrap();
    assert_eq!(record.versions.len(), 2);
    assert_eq!(record.versions[0].body, "## v1.0\nReleased on time.");
    assert_eq!(record.versions[1].body, "## v1.1\nFixed the critical bug.");
    // human_edit_diff is None because no operator-authored version
    assert!(
        record.human_edit_diff().is_none(),
        "no operator version yet"
    );

    // Step 5: list — should show 1 record
    let result = list.execute(serde_json::json!({})).await.unwrap();
    assert!(!result.is_error);
    let records: Vec<ArtifactRecord> = serde_json::from_str(&result.text()).unwrap();
    assert_eq!(records.len(), 1);
    assert_eq!(records[0].id, id);

    // Step 6: operator diff — lines between v2 (agent) and v3 (operator)
    let now = tiny_artifacts::now_millis();
    let mut record = record;
    let v3 = ArtifactVersion::new(
        3,
        "## v1.1\nEdited by human.",
        ArtifactAuthor::Operator,
        "alice",
        now,
    );
    record.push_version(v3);
    let diff = record.human_edit_diff();
    assert!(diff.is_some(), "operator version should produce a diff");
    let diff = diff.unwrap();
    assert_eq!(diff.from_version, 2);
    assert_eq!(diff.to_version, 3);
    assert_eq!(diff.added, 1);
    assert_eq!(diff.removed, 1);
    assert_eq!(diff.lines.len(), 3); // equal + delete + insert
}

#[tokio::test]
async fn error_paths() {
    let store: Arc<dyn ArtifactStore> = Arc::new(MemStore(std::sync::Mutex::new(Vec::new())));
    let artifacts = Arc::new(Artifacts::new(store));
    let create = CreateArtifactTool::new(artifacts.clone(), Author::agent("agent"));
    let read = ReadArtifactTool::new(artifacts.clone());
    let update = UpdateArtifactTool::new(artifacts.clone(), Author::agent("agent"));

    // Argument validation failures surface as `Err` from `execute` (the
    // tool could not run at all), while domain failures like a missing
    // artifact surface as `Ok(ToolResult::error(...))` (the tool ran and
    // said no). See tinytools `Tool::execute` docs.

    // Invalid kind is rejected.
    let result = create
        .execute(serde_json::json!({
            "kind": "pdf",
            "title": "T",
            "body": "b"
        }))
        .await;
    assert!(result.is_err(), "invalid kind must be an Err");

    // Empty title is rejected.
    let result = create
        .execute(serde_json::json!({
            "kind": "text",
            "title": "   ",
            "body": "b"
        }))
        .await;
    assert!(result.is_err(), "blank title must be an Err");

    // Empty body is rejected.
    let result = create
        .execute(serde_json::json!({
            "kind": "text",
            "title": "T",
            "body": ""
        }))
        .await;
    assert!(result.is_err(), "empty body must be an Err");

    // Missing required create args are rejected.
    let result = create
        .execute(serde_json::json!({"kind": "text", "title": "T"}))
        .await;
    assert!(result.is_err(), "missing body must be an Err");

    // read_artifact on a missing id is a reported tool error.
    let result = read
        .execute(serde_json::json!({"artifact_id": "does-not-exist"}))
        .await
        .unwrap();
    assert!(result.is_error, "read of missing artifact must be an error");

    // update_artifact on a missing id is a reported tool error.
    let result = update
        .execute(serde_json::json!({
            "artifact_id": "does-not-exist",
            "body": "new"
        }))
        .await
        .unwrap();
    assert!(
        result.is_error,
        "update of missing artifact must be an error"
    );

    // A happy-path create still works after all the rejections.
    let result = create
        .execute(serde_json::json!({
            "kind": "html",
            "title": "Page",
            "body": "<p>hi</p>"
        }))
        .await
        .unwrap();
    assert!(!result.is_error, "valid html create must succeed");
}

//! The tools' contract with the model: names, schemas, permissions, and how a
//! malformed call or a failing store surfaces.

// Unwrapping is fine in tests (AGENTS.md); the workspace lints keep it out of
// library code.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::sync::Arc;

use serde_json::{json, Value};
use tiny_artifacts::{
    registered_tools, ArtifactRecord, ArtifactStore, Artifacts, Author, CreateArtifactTool,
    DeleteArtifactTool, ListArtifactsTool, ReadArtifactTool, ShareArtifactTool, UpdateArtifactTool,
};
use tinytools::{PermissionLevel, Tool};

/// A store that fails every call, as a backend outage would.
struct DownStore;

#[async_trait::async_trait]
impl ArtifactStore for DownStore {
    async fn list(&self) -> anyhow::Result<Vec<ArtifactRecord>> {
        anyhow::bail!("store down")
    }
    async fn get(&self, _id: &str) -> anyhow::Result<Option<ArtifactRecord>> {
        anyhow::bail!("store down")
    }
    async fn upsert(&self, _artifact: &ArtifactRecord) -> anyhow::Result<()> {
        anyhow::bail!("store down")
    }
    async fn delete(&self, _id: &str) -> anyhow::Result<bool> {
        anyhow::bail!("store down")
    }
}

fn down() -> Arc<Artifacts> {
    Arc::new(Artifacts::new(Arc::new(DownStore)))
}

fn author() -> Author {
    Author::agent("agent")
}

fn all_tools(artifacts: &Arc<Artifacts>) -> Vec<Box<dyn Tool>> {
    vec![
        Box::new(CreateArtifactTool::new(artifacts.clone(), author())),
        Box::new(ReadArtifactTool::new(artifacts.clone())),
        Box::new(UpdateArtifactTool::new(artifacts.clone(), author())),
        Box::new(ListArtifactsTool::new(artifacts.clone())),
        Box::new(DeleteArtifactTool::new(artifacts.clone())),
        Box::new(ShareArtifactTool::new(artifacts.clone())),
    ]
}

#[test]
fn the_default_set_is_the_four_safe_tools_in_catalogue_order() {
    let names: Vec<String> = registered_tools(down(), author())
        .iter()
        .map(|t| t.name().to_string())
        .collect();
    assert_eq!(
        names,
        [
            "create_artifact",
            "read_artifact",
            "update_artifact",
            "list_artifacts"
        ]
    );
}

#[test]
fn every_tool_describes_itself_and_declares_an_object_schema() {
    for tool in all_tools(&down()) {
        let name = tool.name().to_string();
        assert!(!tool.description().trim().is_empty(), "{name}");
        let schema: Value = tool.parameters_schema();
        assert_eq!(schema["type"], "object", "{name}");
        assert!(schema["properties"].is_object(), "{name}");
        // Whatever a tool requires is declared among its properties.
        for required in schema["required"].as_array().into_iter().flatten() {
            let key = required.as_str().unwrap();
            assert!(schema["properties"].get(key).is_some(), "{name}: {key}");
        }
    }
}

#[test]
fn tools_debug_print_their_type_only() {
    let artifacts = down();
    let shown = [
        format!("{:?}", CreateArtifactTool::new(artifacts.clone(), author())),
        format!("{:?}", ReadArtifactTool::new(artifacts.clone())),
        format!("{:?}", UpdateArtifactTool::new(artifacts.clone(), author())),
        format!("{:?}", ListArtifactsTool::new(artifacts.clone())),
        format!("{:?}", DeleteArtifactTool::new(artifacts.clone())),
        format!("{:?}", ShareArtifactTool::new(artifacts)),
    ];
    for text in shown {
        assert!(
            text.contains("Artifact") && text.ends_with("Tool { .. }"),
            "{text}"
        );
    }
}

#[test]
fn permissions_and_concurrency_match_what_each_tool_does() {
    let artifacts = down();
    let expected = [
        ("create_artifact", PermissionLevel::Write, false),
        ("read_artifact", PermissionLevel::ReadOnly, true),
        ("update_artifact", PermissionLevel::Write, false),
        ("list_artifacts", PermissionLevel::ReadOnly, true),
        ("delete_artifact", PermissionLevel::Dangerous, false),
        ("share_artifact", PermissionLevel::Execute, false),
    ];
    let tools = all_tools(&artifacts);
    for (name, permission, concurrent) in expected {
        let tool = tools.iter().find(|t| t.name() == name).unwrap();
        assert_eq!(tool.permission_level(), permission, "{name}");
        assert_eq!(tool.is_concurrency_safe(&json!({})), concurrent, "{name}");
    }
    let share = tools.iter().find(|t| t.name() == "share_artifact").unwrap();
    assert!(share.external_effect(), "sharing leaves the host");
}

#[tokio::test]
async fn a_failing_store_is_an_error_not_a_tool_result() {
    for tool in all_tools(&down()) {
        let args = match tool.name() {
            "create_artifact" => json!({ "kind": "text", "title": "T", "body": "x" }),
            "list_artifacts" => json!({}),
            _ => json!({ "artifact_id": "a-1", "body": "x" }),
        };
        let name = tool.name().to_string();
        if name == "share_artifact" {
            // No publisher: refused before the store is touched.
            assert!(tool.execute(args).await.unwrap().is_error, "{name}");
        } else {
            assert!(
                tool.execute(args).await.is_err(),
                "{name} must surface the outage"
            );
        }
    }
}

#[tokio::test]
async fn a_file_kind_without_a_path_is_a_malformed_call() {
    let artifacts = Arc::new(Artifacts::new(Arc::new(DownStore)));
    let create = CreateArtifactTool::new(artifacts, author());
    assert!(create
        .execute(json!({ "kind": "image", "title": "Logo" }))
        .await
        .is_err());
}

//! The ready-made file-system store.

// Unwrapping is fine in tests (AGENTS.md); the workspace lints keep it out of
// library code.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::path::PathBuf;

use tiny_artifacts::{ArtifactKind, ArtifactRecord, ArtifactStore, FsArtifactStore};

fn dir() -> PathBuf {
    std::env::temp_dir().join(format!("tiny-artifacts-fs-{}", uuid::Uuid::new_v4()))
}

fn record(id: &str, updated: u64) -> ArtifactRecord {
    let mut r = ArtifactRecord::new(id, id, ArtifactKind::Markdown, "# hi", "agent", 1);
    r.updated_at_millis = updated;
    r
}

#[tokio::test]
async fn records_round_trip_and_list_newest_first() {
    let root = dir().join("versioned");
    let store = FsArtifactStore::new(&root);
    // The directory does not exist yet: nothing stored, no error.
    assert!(store.list().await.unwrap().is_empty());
    assert!(store.get("a").await.unwrap().is_none());

    store.upsert(&record("old", 1)).await.unwrap();
    store.upsert(&record("new", 2)).await.unwrap();
    let ids: Vec<String> = store
        .list()
        .await
        .unwrap()
        .into_iter()
        .map(|r| r.id)
        .collect();
    assert_eq!(ids, ["new", "old"]);
    assert_eq!(store.get("old").await.unwrap(), Some(record("old", 1)));

    // Replacing keeps one file per artifact and leaves no staging files.
    store.upsert(&record("old", 3)).await.unwrap();
    let names: Vec<String> = std::fs::read_dir(&root)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    let mut names = names;
    names.sort();
    assert_eq!(names, ["new.json", "old.json"]);

    assert!(store.delete("old").await.unwrap());
    assert!(!store.delete("old").await.unwrap());
    assert_eq!(store.list().await.unwrap().len(), 1);
}

#[tokio::test]
async fn unsafe_ids_are_refused() {
    let store = FsArtifactStore::new(dir());
    for id in ["", ".", "..", "../x", "a/b", "a\\b", ".hidden"] {
        assert!(store.get(id).await.is_err(), "`{id}` must be refused");
        assert!(
            store.upsert(&record(id, 1)).await.is_err(),
            "`{id}` must be refused"
        );
    }
}

